    address0, ce0,
    
    q0, 
     
    address1, ce1,
    d1, we1, 
    
    
    reset, clk);

parameter DataWidth = 256;
parameter AddressWidth = 10;
parameter AddressRange = 672;
parameter COL_WIDTH = 8;
parameter NUM_COL = (DataWidth/COL_WIDTH);
 
input[AddressWidth-1:0] address0;
input ce0;

output reg[DataWidth-1:0] q0; 
 
input[AddressWidth-1:0] address1;
input ce1;
input[DataWidth-1:0] d1;
input[NUM_COL-1:0] we1; 


input reset;
input clk;

(* ram_style = "hls_ultra" , cascade_height = 1 *)reg [DataWidth-1:0] ram[0:AddressRange-1];


genvar i;

 



always @(posedge clk) begin 
    if (ce0) begin
        q0 <= ram[address0];
    end
end 

 
 

generate
    for (i=0;i<NUM_COL;i=i+1) begin
        always @(posedge clk) begin
            if (ce1) begin
                if (we1[i])
                    ram[address1][i*COL_WIDTH +: COL_WIDTH] <= d1[i*COL_WIDTH +: COL_WIDTH]; 
            end
        end
    end
endgenerate




 


endmodule

