module EXP_QUANT_start_for_do_quant_U0
#(parameter
    MEM_STYLE   = "shiftReg",
    DATA_WIDTH  = 1,
    ADDR_WIDTH  = 1,
    DEPTH       = 2)
(
    // system signal
    input  wire                  clk,
    input  wire                  reset,

    // write
    output wire                  if_full_n,
    input  wire                  if_write_ce,
    input  wire                  if_write,
    input  wire [DATA_WIDTH-1:0] if_din,
    
    // read 
    output wire                  if_empty_n,
    input  wire                  if_read_ce,
    input  wire                  if_read,
    output wire [DATA_WIDTH-1:0] if_dout
);
//------------------------Parameter----------------------

//------------------------Local signal-------------------
wire [ADDR_WIDTH-1:0] addr;
wire                  push;
wire                  pop;
reg signed [ADDR_WIDTH:0]   mOutPtr;
reg                   empty_n = 1'b0;
reg                   full_n  = 1'b1;
// with almost full?  no 
//------------------------Instantiation------------------
EXP_QUANT_start_for_do_quant_U0_ShiftReg 
#(  .DATA_WIDTH (DATA_WIDTH),
    .ADDR_WIDTH (ADDR_WIDTH),
    .DEPTH      (DEPTH))
U_EXP_QUANT_start_for_do_quant_U0_ShiftReg (
    .clk        (clk),
    .we         (push),
    .addr       (addr),
    .din        (if_din),
    .dout       (if_dout)
);
//------------------------Task and function--------------

//------------------------Body---------------------------
// has num_data_valid ?  no 

// has almost full ? 
assign if_full_n  = full_n; //no 
assign if_empty_n = empty_n;

assign push = (if_write & if_write_ce) & full_n;
assign pop  = (if_read & if_read_ce) & empty_n;
assign addr = mOutPtr[ADDR_WIDTH] == 1'b0 ? mOutPtr[ADDR_WIDTH-1:0]:{ADDR_WIDTH{1'b0}};

// full_n
always @(posedge clk ) begin
    if (reset == 1'b1)
        full_n <= 1'b1;
    else if (push & ~pop) begin
        if (mOutPtr == DEPTH - 2)
            full_n <= 1'b0;
    end
    else if (~push & pop)
        full_n <= 1'b1;
end

// almost_full_n 

// empty_n
always @(posedge clk ) begin
    if (reset == 1'b1)
        empty_n <= 1'b0;
    else if (push & ~pop)
        empty_n <= 1'b1;
    else if (~push & pop) begin
        if (mOutPtr == 0)
            empty_n <= 1'b0;
    end
end

// mOutPtr
always @(posedge clk ) begin
    if (reset == 1'b1)
        mOutPtr <= {ADDR_WIDTH+1{1'b1}};
    else if (push & ~pop)
        mOutPtr <= mOutPtr + 1'b1;
    else if (~push & pop)
        mOutPtr <= mOutPtr - 1'b1;
end

endmodule  


module EXP_QUANT_start_for_do_quant_U0_ShiftReg
#(parameter
    DATA_WIDTH  = 1,
    ADDR_WIDTH  = 1,
    DEPTH       = 2)
(
    input  wire                  clk,
    input  wire                  we,
    input  wire [ADDR_WIDTH-1:0] addr,
    input  wire [DATA_WIDTH-1:0] din,
    output wire [DATA_WIDTH-1:0] dout
);

reg [DATA_WIDTH-1:0] SRL_SIG [0:DEPTH-1];
integer i;

always @ (posedge clk) begin
    if (we) begin
        for (i=0; i<DEPTH-1; i=i+1)
            SRL_SIG[i+1] <= SRL_SIG[i];
        SRL_SIG[0] <= din;
    end
end

assign dout = SRL_SIG[addr];

endmodule
