    ap_block_state1 = ((ap_done_reg == 1'b1) | (ap_start == 1'b0));
end

always @ (*) begin
    ap_block_state10 = ((regslice_both_out_stream_U_apdone_blk == 1'b1) | (regslice_both_z_stream_U_apdone_blk == 1'b1) | (regslice_both_xBC_stream_U_apdone_blk == 1'b1) | (regslice_both_dt_stream_U_apdone_blk == 1'b1));
end

always @ (*) begin
    ap_rst_n_inv = ~ap_rst_n;
end

assign dt_stream_TVALID = regslice_both_dt_stream_U_vld_out;

assign gemm_stream_TREADY = regslice_both_gemm_stream_U_ack_in;

assign grp_GEMM_DEMUX_Pipeline_VITIS_LOOP_57_1_fu_40_ap_start = grp_GEMM_DEMUX_Pipeline_VITIS_LOOP_57_1_fu_40_ap_start_reg;

assign grp_GEMM_DEMUX_Pipeline_VITIS_LOOP_57_1_fu_40_xBC_stream_TREADY = (xBC_stream_TREADY_int_regslice & ap_CS_fsm_state3);

assign grp_GEMM_DEMUX_Pipeline_VITIS_LOOP_64_2_VITIS_LOOP_65_3_fu_48_ap_start = grp_GEMM_DEMUX_Pipeline_VITIS_LOOP_64_2_VITIS_LOOP_65_3_fu_48_ap_start_reg;

assign grp_GEMM_DEMUX_Pipeline_VITIS_LOOP_64_2_VITIS_LOOP_65_3_fu_48_dt_stream_TREADY = (dt_stream_TREADY_int_regslice & ap_CS_fsm_state6);

assign grp_GEMM_DEMUX_Pipeline_VITIS_LOOP_64_2_VITIS_LOOP_65_3_fu_48_xBC_stream_TREADY = (xBC_stream_TREADY_int_regslice & ap_CS_fsm_state6);

assign grp_GEMM_DEMUX_Pipeline_VITIS_LOOP_64_2_VITIS_LOOP_65_3_fu_48_z_stream_TREADY = (z_stream_TREADY_int_regslice & ap_CS_fsm_state6);

assign grp_GEMM_DEMUX_Pipeline_VITIS_LOOP_80_4_fu_60_ap_start = grp_GEMM_DEMUX_Pipeline_VITIS_LOOP_80_4_fu_60_ap_start_reg;

assign grp_GEMM_DEMUX_Pipeline_VITIS_LOOP_80_4_fu_60_out_stream_TREADY = (out_stream_TREADY_int_regslice & ap_CS_fsm_state9);

assign out_stream_TVALID = regslice_both_out_stream_U_vld_out;

assign xBC_stream_TVALID = regslice_both_xBC_stream_U_vld_out;

assign z_stream_TVALID = regslice_both_z_stream_U_vld_out;

